package com.example.appointment.queue;
import com.example.appointment.appointment.*; import com.example.appointment.common.DomainException; import com.example.appointment.staff.*; import com.example.appointment.user.*; import java.util.*; import javax.validation.constraints.NotNull; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.transaction.annotation.Transactional;
@RestController @Transactional public class QueueController {private final QueueEntryRepository queues;private final StaffProfileRepository staff;private final AppointmentService service;private final QueuePublisher publisher;public QueueController(QueueEntryRepository q,StaffProfileRepository s,AppointmentService a,QueuePublisher p){queues=q;staff=s;service=a;publisher=p;} @GetMapping("/api/staff/queue") @PreAuthorize("hasAnyRole('STAFF','ADMIN')") List<AppointmentController.QueueResponse> list(@RequestParam Long staffId,Authentication a){authorize(staffId,a);List<AppointmentController.QueueResponse>x=new ArrayList<>();queues.waiting(staffId).forEach(q->x.add(AppointmentController.queue(q)));return x;} @GetMapping("/api/queue/status") AppointmentController.QueueResponse customer(@RequestParam Long appointmentId,Authentication a){service.authorized(appointmentId,(User)a.getPrincipal(),false);return AppointmentController.queue(queues.findByAppointmentId(appointmentId).orElseThrow(()->DomainException.notFound("Queue entry not found")));} @PostMapping("/api/staff/queue/next") @PreAuthorize("hasAnyRole('STAFF','ADMIN')") AppointmentController.QueueResponse next(@RequestBody Next r,Authentication a){authorize(r.staffId,a);List<QueueEntry> waiting=queues.lockWaiting(r.staffId);QueueEntry q=waiting.stream().filter(x->r.serviceId==null||x.getAppointment().getService().getId().equals(r.serviceId)).findFirst().orElseThrow(()->DomainException.conflict("QUEUE_EMPTY","No waiting customer"));q.call();queues.save(q);service.recalculate(r.staffId);publisher.update(q);return AppointmentController.queue(q);} @PostMapping("/api/staff/queue/{id}/call") @PreAuthorize("hasAnyRole('STAFF','ADMIN')") AppointmentController.QueueResponse call(@PathVariable Long id,Authentication a){QueueEntry q=queues.findById(id).orElseThrow(()->DomainException.notFound("Queue entry not found"));authorize(q.getAppointment().getStaff().getId(),a);q.call();queues.save(q);service.recalculate(q.getAppointment().getStaff().getId());publisher.update(q);return AppointmentController.queue(q);} @PatchMapping("/api/staff/queue/{id}/no-show") @PreAuthorize("hasAnyRole('STAFF','ADMIN')") AppointmentController.QueueResponse noShow(@PathVariable Long id,Authentication a){QueueEntry q=queues.findById(id).orElseThrow(()->DomainException.notFound("Queue entry not found"));authorize(q.getAppointment().getStaff().getId(),a);q.noShow();queues.save(q);service.recalculate(q.getAppointment().getStaff().getId());publisher.update(q);return AppointmentController.queue(q);} private void authorize(Long id,Authentication a){User u=(User)a.getPrincipal();if(u.getRole()!=Role.ADMIN&&!staff.findByUserId(u.getId()).map(s->s.getId().equals(id)).orElse(false))throw new org.springframework.security.access.AccessDeniedException("Not assigned staff");} public static class Next{@NotNull public Long staffId;public Long serviceId;} }
